import React from 'react';
import * as ReactRouterDOM from 'react-router-dom';
const { Link } = ReactRouterDOM;

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  children: React.ReactNode;
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  className?: string;
  href?: string;
  to?: string;
  target?: string;
  rel?: string;
}

const Button: React.FC<ButtonProps> = ({
  children,
  variant = 'primary',
  size = 'md',
  className = '',
  href,
  to,
  target,
  rel,
  ...props
}) => {
  const baseClasses = 'inline-flex items-center justify-center font-semibold rounded-xl focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200 active:scale-[0.97] min-h-[44px]';

  const variantClasses = {
    primary: 'bg-primary-600 text-white hover:bg-primary-700 shadow-sm focus:ring-primary-500',
    secondary: 'bg-gray-700 text-white hover:bg-gray-800 shadow-sm focus:ring-gray-600',
    outline: 'border border-primary-600 text-primary-600 hover:bg-primary-50 dark:hover:bg-primary-900/20 focus:ring-primary-500',
    ghost: 'text-primary-600 hover:bg-primary-50 dark:hover:bg-primary-900/20 focus:ring-primary-500',
  };

  const sizeClasses = {
    sm: 'px-3 py-1.5 text-sm',
    md: 'px-5 py-2.5 text-base',
    lg: 'px-8 py-4 text-lg',
  };

  const classes = `${baseClasses} ${variantClasses[variant]} ${sizeClasses[size]} ${className}`;

  if (to) {
    return (
      <Link to={to} className={classes} target={target} rel={rel} {...(props as any)}>
        {children}
      </Link>
    );
  }

  if (href) {
    return (
      <a href={href} className={classes} target={target} rel={rel} {...(props as any)}>
        {children}
      </a>
    );
  }

  return (
    <button className={classes} {...props}>
      {children}
    </button>
  );
};

export default Button;

import React, { useState, useEffect, useRef, Suspense, lazy } from 'react';
import { useAppContext } from '../../context/AppContext';
import { useNotifier } from '../../context/NotificationContext';
import { supabase } from '../../lib/supabaseClient';
import Card from '../ui/Card';
import Button from '../ui/Button';
import { XIcon, ClockIcon, PlayIcon, PauseIcon, CheckCircleIcon, FireIcon, RefreshIcon, PencilAltIcon } from '../ui/Icons';
import { UserCourseMaterial } from '../../types';

const AutoSaveField = lazy(() => import('../ui/AutoSaveField'));

interface FocusStudyModalProps {
    material: UserCourseMaterial;
    onClose: () => void;
}

const SESSION_DURATION = 25 * 60; // 25 minutes
const COIN_REWARD = 10;

const FocusStudyModal: React.FC<FocusStudyModalProps> = ({ material, onClose }) => {
    const { currentUser } = useAppContext();
    const { addToast } = useNotifier();

    const [timeLeft, setTimeLeft] = useState(SESSION_DURATION);
    const [isActive, setIsActive] = useState(false);
    const [isCompleted, setIsCompleted] = useState(false);
    const [isProcessingReward, setIsProcessingReward] = useState(false);
    const [notes, setNotes] = useState('');

    useEffect(() => {
        let interval: number | null = null;
        if (isActive && timeLeft > 0) {
            interval = window.setInterval(() => {
                setTimeLeft((time) => time - 1);
            }, 1000);
        } else if (timeLeft === 0 && isActive) {
            setIsActive(false);
            setIsCompleted(true);
            if (interval) clearInterval(interval);
        }
        return () => { if (interval) clearInterval(interval); };
    }, [isActive, timeLeft]);

    const toggleTimer = () => setIsActive(!isActive);
    const resetTimer = () => { setTimeLeft(SESSION_DURATION); setIsActive(false); setIsCompleted(false); };

    const handleClaimReward = async () => {
        if (!currentUser || !supabase || isProcessingReward) return;
        setIsProcessingReward(true);
        try {
            const { error } = await supabase.from('coin_transactions').insert({
                user_id: currentUser.id,
                source_type: 'task',
                source_id: material.id,
                coin_amount: COIN_REWARD,
                status: 'pending',
                reason: `Focus Session: ${material.title}`
            });
            if (error) throw error;
            addToast(`Session Complete! +${COIN_REWARD} coins pending.`, 'success');
            onClose();
        } catch (error: any) {
            addToast(error.message, 'error');
            setIsProcessingReward(false);
        }
    };

    const formatTime = (seconds: number) => {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
    };

    const progressPercentage = ((SESSION_DURATION - timeLeft) / SESSION_DURATION) * 100;

    return (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center">
            {/* Backdrop Close */}
            <div className="absolute inset-0" onClick={onClose}></div>

            <Card className="w-full max-w-lg relative flex flex-col h-[85vh] sm:h-auto sm:max-h-[90vh] rounded-t-3xl sm:rounded-2xl overflow-hidden !p-0 z-10 animate-fade-in-up">
                {/* Drag Handle for Mobile */}
                <div className="w-12 h-1.5 bg-gray-300 dark:bg-gray-600 rounded-full mx-auto my-3 sm:hidden"></div>

                <div className="p-4 sm:p-6 border-b dark:border-gray-700 flex justify-between items-center bg-white dark:bg-dark">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-primary-100 dark:bg-primary-900/30 rounded-xl text-primary-600">
                            <ClockIcon className="w-6 h-6" />
                        </div>
                        <div className="min-w-0">
                            <h2 className="font-bold text-lg sm:text-xl truncate">Deep Study</h2>
                            <p className="text-xs text-gray-400 truncate">{material.title}</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-3 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full min-w-[44px] min-h-[44px] flex items-center justify-center">
                        <XIcon className="w-6 h-6 text-gray-500" />
                    </button>
                </div>

                <div className="overflow-y-auto flex-1 p-6 flex flex-col items-center">
                    <div className="relative mb-8">
                        <div className="w-56 h-56 sm:w-64 sm:h-64 relative flex items-center justify-center">
                            <svg className="w-full h-full transform -rotate-90">
                                <circle cx="50%" cy="50%" r="46%" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-gray-100 dark:text-gray-800" />
                                <circle cx="50%" cy="50%" r="46%" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray="600" strokeDashoffset={600 - (600 * progressPercentage / 100)} className="text-primary-500 transition-all duration-1000 ease-linear rounded-full" />
                            </svg>
                            <div className="absolute inset-0 flex flex-col items-center justify-center">
                                <span className="text-5xl font-mono font-black text-gray-900 dark:text-white tabular-nums">{formatTime(timeLeft)}</span>
                                <span className="text-[10px] text-gray-400 mt-2 uppercase tracking-[0.2em] font-bold">{isActive ? 'Flowing' : 'Paused'}</span>
                            </div>
                        </div>
                    </div>

                    <div className="flex gap-4 w-full max-w-sm justify-center mb-8">
                        {!isCompleted ? (
                            <>
                                <Button onClick={toggleTimer} size="lg" className={`flex-1 ${isActive ? 'bg-yellow-500 hover:bg-yellow-600' : 'bg-primary-600 hover:bg-primary-700'}`}>
                                    {isActive ? <PauseIcon className="w-6 h-6" /> : <PlayIcon className="w-6 h-6" />}
                                    <span className="ml-2">{isActive ? 'Pause' : 'Resume'}</span>
                                </Button>
                                <Button onClick={resetTimer} variant="outline" size="lg" className="px-5 border-2"><RefreshIcon className="w-6 h-6" /></Button>
                            </>
                        ) : (
                            <Button onClick={handleClaimReward} size="lg" className="w-full bg-gradient-to-r from-orange-500 to-primary-600 shadow-xl py-5" disabled={isProcessingReward}>
                                <FireIcon className="w-6 h-6 mr-2" />
                                {isProcessingReward ? 'Processing...' : `Claim ${COIN_REWARD} Coins`}
                            </Button>
                        )}
                    </div>

                    <div className="w-full border-t dark:border-gray-800 pt-6">
                        <div className="flex justify-between items-center mb-3">
                            <h3 className="font-bold text-sm flex items-center gap-2 opacity-70"><PencilAltIcon className="w-4 h-4" /> Study Notes</h3>
                        </div>
                        <Suspense fallback={<div className="h-32 bg-gray-100 dark:bg-gray-800 rounded-xl animate-pulse"></div>}>
                            <AutoSaveField
                                as="textarea"
                                storageKey={`study-notes-${material.id}`}
                                value={notes}
                                onChange={(e) => setNotes(e.target.value)}
                                placeholder="Jot down key points here..."
                                className="w-full h-32 p-4 bg-gray-50 dark:bg-gray-800/50 border border-gray-200 dark:border-gray-700 rounded-2xl text-sm focus:ring-primary-500 focus:border-primary-500 resize-none transition-all"
                            />
                        </Suspense>
                    </div>
                </div>
            </Card>
        </div>
    );
};

export default FocusStudyModal;

import React, { useState, useEffect, useRef } from 'react';
import * as ReactRouterDOM from 'react-router-dom';
const { Link } = ReactRouterDOM;
import { MenuIcon, SunIcon, MoonIcon, ChevronDownIcon, BellIcon } from '../ui/Icons';
import { useAppContext } from '../../context/AppContext';
import { useNotifier } from '../../context/NotificationContext';
import Avatar from '../auth/Avatar';
import { supabase } from '../../lib/supabaseClient';

const Navbar: React.FC = () => {
  const { toggleSidebar, currentUser, theme, toggleTheme } = useAppContext();
  const { notifications, unreadCount } = useNotifier();
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isNotifOpen, setIsNotifOpen] = useState(false);

  const profileRef = useRef<HTMLDivElement>(null);
  const notifRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (profileRef.current && !profileRef.current.contains(event.target as Node)) setIsProfileOpen(false);
      if (notifRef.current && !notifRef.current.contains(event.target as Node)) setIsNotifOpen(false);
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  return (
    <header className="bg-white dark:bg-dark shadow-sm h-16 flex items-center justify-between px-4 sm:px-6 z-10 flex-shrink-0 border-b border-gray-100 dark:border-gray-800">
      <div className="flex items-center">
        <button onClick={toggleSidebar} className="p-2 -ml-2 text-gray-500 dark:text-gray-400 rounded-xl hover:bg-gray-100 dark:hover:bg-gray-800 min-w-[44px] min-h-[44px] flex items-center justify-center transition-colors">
          <MenuIcon />
        </button>
        <h1 className="text-lg font-bold ml-2 text-gray-800 dark:text-white hidden xs:block">
          {currentUser?.full_name?.split(' ')[0] || 'Member'}
        </h1>
      </div>

      <div className="flex items-center space-x-1 sm:space-x-2">
        <button onClick={toggleTheme} className="p-2 rounded-xl text-gray-500 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800 min-w-[44px] min-h-[44px] flex items-center justify-center transition-colors">
          {theme === 'dark' ? <SunIcon className="w-6 h-6 text-yellow-400" /> : <MoonIcon className="w-6 h-6" />}
        </button>

        <div className="relative" ref={notifRef}>
            <button 
                onClick={() => setIsNotifOpen(!isNotifOpen)} 
                className="p-2 rounded-xl text-gray-500 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800 min-w-[44px] min-h-[44px] flex items-center justify-center relative transition-colors"
                aria-label="Notifications"
            >
                <BellIcon className="w-6 h-6" />
                {unreadCount > 0 && (
                    <span className="absolute top-2.5 right-2.5 block h-2.5 w-2.5 rounded-full bg-red-500 ring-2 ring-white dark:ring-dark"></span>
                )}
            </button>
            {isNotifOpen && (
                <div className="absolute right-0 mt-3 w-[85vw] sm:w-80 bg-white dark:bg-dark rounded-2xl shadow-2xl z-20 border border-gray-100 dark:border-gray-800 overflow-hidden animate-fade-in-up">
                    <div className="p-4 font-bold border-b dark:border-gray-800 flex justify-between items-center bg-gray-50/50 dark:bg-gray-800/30">
                        <span>Updates</span>
                        {unreadCount > 0 && <span className="text-[10px] font-black bg-primary-500 text-white rounded-full px-2 py-0.5 uppercase tracking-widest">{unreadCount} New</span>}
                    </div>
                    <ul className="max-h-[60vh] overflow-y-auto">
                        {notifications.slice(0, 5).map(notif => (
                            <li key={notif.id} className="border-b dark:border-gray-800/50 last:border-b-0">
                                <Link to={notif.link || '/notifications'} onClick={() => setIsNotifOpen(false)} className="flex items-start gap-3 p-4 hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors">
                                    {!notif.is_read && <div className="w-2 h-2 mt-2 bg-primary-500 rounded-full flex-shrink-0"></div>}
                                    <p className={`text-sm leading-snug ${notif.is_read ? 'text-gray-400' : 'text-gray-800 dark:text-gray-100 font-medium'}`}>{notif.message}</p>
                                </Link>
                            </li>
                        ))}
                    </ul>
                    <Link to="/notifications" onClick={() => setIsNotifOpen(false)} className="block text-center py-3 text-xs font-bold text-primary-600 dark:text-primary-400 bg-gray-50/50 dark:bg-gray-800/30 uppercase tracking-widest hover:bg-primary-50 transition-colors">
                        View All
                    </Link>
                </div>
            )}
        </div>

        <div className="relative" ref={profileRef}>
          <button onClick={() => setIsProfileOpen(!isProfileOpen)} className="flex items-center pl-2 hover:opacity-80 transition-opacity min-h-[44px]">
            <Avatar src={currentUser?.avatar_url} alt={currentUser?.full_name || 'User'} size="md" className="border-2 border-white dark:border-gray-800 shadow-sm" />
            <ChevronDownIcon className="w-4 h-4 ml-1 text-gray-400" />
          </button>
          {isProfileOpen && (
            <div className="absolute right-0 mt-3 w-52 bg-white dark:bg-dark rounded-2xl shadow-2xl py-2 z-20 border border-gray-100 dark:border-gray-800 animate-fade-in-up">
              <Link to="/profile" className="flex items-center px-4 py-3 text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors">My Account</Link>
              <Link to="/developer-settings" className="flex items-center px-4 py-3 text-sm font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors">App Settings</Link>
              <hr className="my-2 border-gray-100 dark:border-gray-800" />
              <button onClick={() => supabase && (supabase.auth as any).signOut()} className="w-full text-left px-4 py-3 text-sm font-bold text-red-500 hover:bg-red-50 dark:hover:bg-red-900/10 transition-colors">Logout</button>
            </div>
          )}
        </div>
      </div>
    </header>
  );
};

