                        disabled={!newMessage.trim()}
                        className="w-11 h-11 flex items-center justify-center bg-primary-600 text-white rounded-full shadow-lg disabled:opacity-50 disabled:grayscale transition-all active:scale-90"
                    >
                        <SendIcon className="w-5 h-5" />
                    </button>
                </form>
            </footer>

            {showEmojiPicker && (
                <div ref={emojiPickerRef} className="absolute bottom-20 left-4 right-4 z-50 animate-spring-up">
                    <EmojiPicker onEmojiClick={(data) => setNewMessage(prev => prev + data.emoji)} width="100%" />
                </div>
            )}

            {contextMenu && (
                <div style={{ top: contextMenu.y, left: contextMenu.x }} className="fixed z-50 bg-white dark:bg-gray-800 rounded-xl shadow-2xl py-1 w-40 border border-gray-100 dark:border-gray-700 animate-fade-in-up">
                    <button onClick={() => handleCopy(contextMenu.message.text)} className="w-full text-left px-4 py-3 text-sm font-bold hover:bg-gray-50 dark:hover:bg-gray-700 flex items-center gap-3">
                        <CopyIcon className="w-4 h-4" /> Copy
                    </button>
                    {contextMenu.message.sender_id === currentUser?.id && (
