                            <TrashIcon className="w-4 h-4" /> Delete
                        </button>
                    )}
                </div>
            )}

            {isInfoModalOpen && <UserProfileModal user={otherUser} isLoading={!otherUser} onClose={() => setIsInfoModalOpen(false)} />}
        </div>
    );
};

