const Dashboard: React.FC = () => {
  const { currentUser, isLoading, isProfileComplete } = useAppContext();
  const [taskAssignments, setTaskAssignments] = useState<TaskAssignment[]>([]);
  const [challenge, setChallenge] = useState<WeeklyChallenge | null>(null);
  const [leaderboard, setLeaderboard] = useState<Partial<UserProfile>[]>([]);
  const [onboardingProgress, setOnboardingProgress] = useState<OnboardingProgress | null>(null);
  const [recentMaterials, setRecentMaterials] = useState<UserCourseMaterial[]>([]);

  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
  const [selectedStudyMaterial, setSelectedStudyMaterial] = useState<UserCourseMaterial | null>(null);

  useEffect(() => {
    if (currentUser && supabase) {
      const fetchDashboardData = async () => {
        const todayStart = new Date();
        todayStart.setHours(0, 0, 0, 0);
        const todayEnd = new Date();
        todayEnd.setHours(23, 59, 59, 999);

        // Fetch all data in parallel
        const [
            tasksRes,
            challengeRes,
            leaderboardRes,
            onboardingRes,
            materialsRes
        ] = await Promise.all([
            supabase
              .from('tasks_assignments')
              .select('*, tasks!inner(*)')
              .eq('assignee_id', currentUser.id)
              .gte('created_at', todayStart.toISOString())
              .lte('created_at', todayEnd.toISOString())
              .limit(3),
            supabase
              .from('weekly_challenges')
              .select('*')
              .lte('start_date', new Date().toISOString())
              .gte('due_date', new Date().toISOString())
              .order('created_at', { ascending: false })
              .limit(1)
              .maybeSingle(),
            supabase
              .from('profiles')
              .select('id, full_name, avatar_url, coins')
              .order('coins', { ascending: false })
              .limit(4),
            supabase
                .from('onboarding_progress')
                .select('*')
                .eq('user_id', currentUser.id)
                .maybeSingle(),
            supabase
                .from('user_course_materials')
                .select('*, courses(code, name)')
                .eq('status', 'approved')
                .order('created_at', { ascending: false })
                .limit(3)
        ]);

        if (tasksRes.error) console.error('Error fetching tasks', tasksRes.error.message);
        else setTaskAssignments((tasksRes.data as TaskAssignment[]) || []);

        if (challengeRes.error) console.error('Error fetching challenge', challengeRes.error.message);
        else setChallenge(challengeRes.data);

        if (leaderboardRes.error) console.error('Error fetching leaderboard', leaderboardRes.error.message);
        else setLeaderboard(leaderboardRes.data || []);

        if (onboardingRes.error) {
            if (onboardingRes.error.code !== '42P01') {
                console.error('Error fetching onboarding progress', onboardingRes.error.message);
            }
            setOnboardingProgress(null);
        } else {
            setOnboardingProgress(onboardingRes.data as OnboardingProgress);
        }

        if (materialsRes.error) console.error('Error fetching recent materials', materialsRes.error.message);
        else setRecentMaterials(materialsRes.data as any || []);
      };

      fetchDashboardData();
    }
  }, [currentUser]);

  if (isLoading || !currentUser) {
    return <div className="text-center p-8">Loading your dashboard...</div>;
  }

  return (
    <div className="space-y-6">
      {!isProfileComplete && <CompleteProfileCard />}
      {onboardingProgress && <OnboardingCard progress={onboardingProgress} />}

      <UploadCtaCard onOpen={() => setIsUploadModalOpen(true)} />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main Content Column */}
        <div className="lg:col-span-2 space-y-6">
          <ScriptureOfTheDay />
          <DailyTasks tasks={taskAssignments} />
          <WebsiteCtaCard />
        </div>

        {/* Sidebar Column */}
        <div className="lg:col-span-1 space-y-6">
          <MyProgressCard user={currentUser} />
          <GameCenterPromoCard />
          {/* New Exam Prep Shortcut - HIDDEN FOR NOW
          <ExamPrepCard materials={recentMaterials} onStudy={setSelectedStudyMaterial} />
          */}
          <WeeklyChallengeCard challenge={challenge} />
          <MiniLeaderboard leaderboard={leaderboard} />
        </div>
      </div>

      {isUploadModalOpen && <UploadMaterialModal onClose={() => setIsUploadModalOpen(false)} />}

      {selectedStudyMaterial && (
          <FocusStudyModal 
              material={selectedStudyMaterial} 
              onClose={() => setSelectedStudyMaterial(null)} 
          />
      )}
    </div>
  );
};

export default Dashboard;

