                            <MenuIcon className="w-6 h-6" />
                        </button>
                        <h1 className="text-xl font-bold ml-2">Chats</h1>
                    </div>
                    <div className="flex items-center gap-1 sm:gap-2">
                        {/* New Chat Button (Moved from FAB) */}
                        <button
                            onClick={handleOpenNewChatModal}
                            className="p-2 text-primary-600 dark:text-primary-400 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700/50 transition-colors"
                            aria-label="Start new chat"
                        >
                            <PlusIcon className="w-6 h-6" />
                        </button>
                        <Avatar src={currentUser?.avatar_url} alt={currentUser?.full_name || 'User'} size="md" className="border-2 border-white dark:border-gray-800 shadow-sm" />
                    </div>
                </header>

                {/* Search */}
                <div className="px-4 py-4 flex-shrink-0">
