    const [isModalLoading, setIsModalLoading] = useState(false);

    const isViewingConversationOnMobile = !!activeUserId;

    const fetchConversations = useCallback(async () => {
        if (!supabase) return;
        setLoading(true);
        const { data, error } = await supabase.rpc('get_chat_history');
        if (!error) setConversations((data as ChatHistoryItem[]) || []);
        setLoading(false);
    }, []);

    useEffect(() => { fetchConversations(); }, [fetchConversations]);

    useEffect(() => {
        if (!supabase || !currentUser) return;
        const channel = supabase.channel('public:messages').on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'messages' }, () => {
            fetchConversations();
            refreshNotifications();
        }).subscribe();
        return () => { supabase.removeChannel(channel); };
    }, [supabase, currentUser, fetchConversations, refreshNotifications]);

    const filteredChats = useMemo(() => {
        if (!searchTerm) return conversations;
        return conversations.filter(chat => chat.other_user_name?.toLowerCase().includes(searchTerm.toLowerCase()));
    }, [searchTerm, conversations]);

    const handleOpenNewChatModal = async () => {
        setIsNewChatModalOpen(true);
        if (allUsers.length === 0) { 
            setLoadingUsers(true);
            if (!supabase || !currentUser) return;
            const { data, error } = await supabase.from('profiles').select('*').neq('id', currentUser.id);
            if (!error) setAllUsers((data as UserProfile[]) || []);
            setLoadingUsers(false);
