import { ArrowLeftIcon, InformationCircleIcon, EmojiIcon, PaperclipIcon, SendIcon, XIcon, UserIcon, CoinIcon, StarIcon, UsersIcon, ChatIcon, CopyIcon, TrashIcon, PauseIcon, PlayIcon } from '../components/ui/Icons';
